/** An asynchronous unit of work. result has the shape the synchronous call would have returned. */
export interface Job {
  attempts: number;
  created_at: string;
  error: JobError | null;
  /** When the job and its result are deleted */
  expires_at: string;
  finished_at: string | null;
  /** A public summary of the inputs: file ids and pages, never bytes or URLs */
  input: JobInput;
  job_id: string;
  /** The key that created the job (empty for console calls) */
  key_id?: string;
  links: JobLinks;
  operation: string;
  progress: JobProgress | null;
  /** The request that created the job */
  request_id?: string;
  /** Set when succeeded: the operation's data, with output files as file objects and fresh signed links */
  result: Record<string, unknown> | null;
  service: string;
  started_at: string | null;
  status: "queued" | "processing" | "succeeded" | "failed" | "cancelled";
  trace_id?: string;
  usage: JobUsage | null;
}

