  listAll(query?: Omit<JobsListQuery, "cursor">, options?: RequestOptions): AsyncIterable<Job> {
    return this.core.paginate<Job>(`/v1/jobs`, query as unknown as Record<string, unknown> | undefined, options);
  }

  /** Waits until the job is succeeded, failed or cancelled, polling with the Retry-After the API sends; throws LowcoApiError when it failed or was cancelled, LowcoTimeoutError at the timeout. */
